using System.Linq;
using System.Text;

public abstract class GeneratorBase
{
    protected static readonly string INDENT = "    ";

    private static readonly string GeneratedMessage = """
        // <auto-generated />
        // This file is automatically generated by a script. Don't edit by hand.

        #nullable restore
        """.NL();

    private bool _generated = false;

    protected StringBuilder _sb;

    public GeneratorBase(StringBuilder sb, bool addGeneratedHeader)
    {
        _sb = sb;
        if (addGeneratedHeader)
        {
            _sb.AppendLine(GeneratedMessage);
        }
    }

    public GeneratorBase()
        : this(new StringBuilder(), true)
    {
    }

    protected abstract Task GenerateCoreAsync();

    public async Task GenerateAsync()
    {
        if (_generated)
        {
            return;
        }

        _generated = true;
        await GenerateCoreAsync();
    }

    public async Task GenerateToAsync(string path)
    {
        await GenerateAsync();

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await File.WriteAllTextAsync(path, _sb.ToString());
    }

    protected static string T<T>(IEnumerable<T> items, Func<T, string> transformer, bool addNewLines = true)
    {
        var result = items.Select(transformer);
        return string.Join(addNewLines ? Environment.NewLine : "", result).Trim();
    }
}
